#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<vector<string>> wordSquares(vector<string>& words) {
        int n = words[0].size();
        unordered_map<string, vector<string>> pref_map;
        for (const auto& w : words) {
            for (int i = 0; i <= n; i++) {
                pref_map[w.substr(0, i)].push_back(w);
            }
        }
        vector<vector<string>> res;
        vector<string> cur;
        auto backtrack = [&](auto& self, int step) -> void {
            if (step == n) {
                res.push_back(cur);
                return;
            }
            string pref = "";
            for (int r = 0; r < step; r++) pref += cur[r][step];
            if (pref_map.count(pref)) {
                for (const auto& cand : pref_map[pref]) {
                    cur.push_back(cand);
                    self(self, step + 1);
                    cur.pop_back();
                }
            }
        };
        backtrack(backtrack, 0);
        return res;
    }
};

import java.util.*;

class Solution {
    private Map<String, List<String>> prefMap = new HashMap<>();
    private List<List<String>> res = new ArrayList<>();

    public List<List<String>> wordSquares(String[] words) {
        prefMap.clear();
        res.clear();
        int n = words[0].length();
        for (String w : words) {
            for (int i = 0; i <= n; i++) {
                String p = w.substring(0, i);
                prefMap.computeIfAbsent(p, k -> new ArrayList<>()).add(w);
            }
        }
        backtrack(0, n, new ArrayList<>());
        return res;
    }

    private void backtrack(int step, int n, List<String> cur) {
        if (step == n) {
            res.add(new ArrayList<>(cur));
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < step; r++) sb.append(cur.get(r).charAt(step));
        String pref = sb.toString();
        if (prefMap.containsKey(pref)) {
            for (String cand : prefMap.get(pref)) {
                cur.add(cand);
                backtrack(step + 1, n, cur);
                cur.remove(cur.size() - 1);
            }
        }
    }
}

var wordSquares = function(words) {
    const n = words[0].length;
    const prefMap = new Map();
    for (const w of words) {
        for (let i = 0; i <= n; i++) {
            const p = w.slice(0, i);
            if (!prefMap.has(p)) prefMap.set(p, []);
            prefMap.get(p).push(w);
        }
    }
    const res = [];
    const cur = [];
    function backtrack(step) {
        if (step === n) {
            res.push([...cur]);
            return;
        }
        let pref = '';
        for (let r = 0; r < step; r++) pref += cur[r][step];
        const cands = prefMap.get(pref) || [];
        for (const cand of cands) {
            cur.push(cand);
            backtrack(step + 1);
            cur.pop();
        }
    }
    backtrack(0);
    return res;
};
